const CFG = $('CONFIG').first().json;
/* Días de gracia antes de dar por vencido un proyecto. 0 = el día siguiente al
   fin ya cuenta como vencido. Subilo si querés margen. */
const gracia = Number(CFG.diasGracia || 0);
const hoy = new Date(); hoy.setHours(0, 0, 0, 0);
const limite = new Date(hoy); limite.setDate(limite.getDate() - gracia);

const proyectos = $('Leer Projects').all().map(i => i.json).filter(r => r && r.id);
const cal = $('Leer Calendar').all().map(i => i.json).filter(r => r && r.project_id);

/* Fechas en formato YYYY-MM-DD, sin zona horaria: se comparan como día calendario */
const parse = (s) => {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(s || '').trim());
  return m ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : null;
};

const salida = [];
const saltados = [];

for (const p of proyectos) {
  const st = String(p.status || '').trim();
  /* solo avanzan los que están corriendo; cierre y completado ya están al final,
     y pre-producción/borrador no se activan solos: eso lo decide una persona */
  if (st !== 'activo' && st !== 'entregando') continue;

  const fechas = [];
  /* 1. fechas de las tareas TEAM23. El chequeo que corría en el navegador NO
        miraba esto, así que un proyecto con fechas solo en tareas nunca avanzaba. */
  let td = {};
  try { td = JSON.parse(p.taskDates_json || '{}') || {}; } catch (e) { td = {}; }
  /* una tarea puede tener varios rangos: el primero en inicio/fin y los demás en
     `rangos`. Si solo se mirara el primero, un proyecto con un tramo posterior
     avanzaría a cierre antes de tiempo. */
  Object.values(td).forEach(d => {
    if (!d) return;
    const tramos = [{ inicio: d.inicio, fin: d.fin }].concat(Array.isArray(d.rangos) ? d.rangos : []);
    tramos.forEach(r => { const f = parse(r && (r.fin || r.inicio)); if (f) fechas.push(f); });
  });
  /* 2. fases y hitos independientes de la hoja Calendar */
  cal.filter(r => String(r.project_id) === String(p.id)).forEach(r => {
    const f = parse(r.fin || r.inicio);
    if (f) fechas.push(f);
  });

  if (!fechas.length) { saltados.push((p.nombre || p.id) + ': sin fechas cargadas'); continue; }

  const fin = new Date(Math.max(...fechas.map(d => d.getTime())));
  if (fin >= limite) continue;   // todavía no venció

  salida.push({ json: {
    id: String(p.id),
    nombre: p.nombre || '',
    status_anterior: st,
    fin: fin.toISOString().slice(0, 10),
    fechas_evaluadas: fechas.length
  } });
}

/* los saltados quedan en el log de la ejecución, para poder auditarlo después */
if (saltados.length) console.log('Sin fechas, no se evalúan: ' + saltados.join(' | '));
console.log('Proyectos a avanzar a cierre: ' + salida.length);
return salida;

/* Corre siempre, aunque no haya habido avances, para que la ejecución diaria
   deje un rastro legible en el log en lugar de terminar vacía. */
let avanzados = [];
try { avanzados = $('Decidir avances').all().map(i => i.json); } catch (e) { avanzados = []; }
const linea = avanzados.length
  ? avanzados.map(a => a.nombre + ' (' + a.status_anterior + ' → cierre, fin ' + a.fin + ')').join(' | ')
  : 'ninguno';
console.log('[wf11] ' + new Date().toISOString().slice(0, 10) + ' — avanzados: ' + linea);
return [{ json: { fecha: new Date().toISOString().slice(0, 10), cantidad: avanzados.length, detalle: avanzados } }];
